    AVDictionary *tmp_opts = NULL;
    AVIOContext *io_ctx = NULL;

    *is_http = 0;

    // Check if the URL uses HTTP protocol
    if (av_strstart(url, "http://", NULL) || av_strstart(url, "https://", NULL)) {
        *is_http = 1;
    }

    // Merge options
    if (opts) {
        av_dict_copy(&tmp_opts, opts, 0);
    }
    if (opts2) {
        av_dict_merge2(&tmp_opts, opts2, 0, AV_DICT_DONT_STRDUP_VAL);
    }

    // Open the URL
    ret = avformat_open_input(&s, url, NULL, &tmp_opts);
    if (ret < 0) {
        av_dict_free(&tmp_opts);
        return ret;
    }

    // Retrieve the AVIOContext
    ret = avformat_find_stream_info(s, NULL);
    if (ret < 0) {
        avformat_close_input(&s);
        av_dict_free(&tmp_opts);
        return ret;
    }

    *pb = s->pb;

    av_dict_free(&tmp_opts);
    return 0;
}

#include <libavformat/avformat.h>
