int open_input_with_options(AVFormatContext *s, AVIOContext **pb, const char *url, AVDictionary *opts, AVDictionary *opts2, int *is_http) {
    int ret;

    // Determine the protocol from the URL
    if (av_strstart(url, "http://", NULL) || av_strstart(url, "https://", NULL)) {
        *is_http = 1;
    } else if (av_strstart(url, "file:", NULL)) {
        *is_http = 0;
    } else {
        // Unknown protocol
        return AVERROR(EINVAL);
    }

    // Merge the two options dictionaries if provided
    AVDictionary *final_opts = NULL;
    if (opts) {
        final_opts = av_dict_copy(final_opts, opts, 0);
    }
    if (opts2) {
        final_opts = av_dict_copy(final_opts, opts2, 0);
    }

    // Open the input URL
    ret = avformat_open_input(&s, url, NULL, &final_opts);
    if (ret < 0) {
        av_dict_free(&final_opts);
        return ret;
    }

    // Retrieve the I/O context
    *pb = s->pb;

    // Clean up the temporary dictionary
    av_dict_free(&final_opts);

    return 0;
}
